/* ---------- sea ---------- */
const DF = { x0: -2400, x1: 2400, z0: -200, z1: 2600, w: 256, h: 160 };
const waterU = { uTime: { value: 0 }, uShallow: { value: C(0x34d0c4) }, uDeep: { value: C(0x0a5f80) }, uFoam: { value: C(0xffffff) }, uDF: { value: null } };
