  for (let i = 0; i < 9; i++) g.add(at(meshOf(box(0.25, 6.4, 0.3), M(0xc9ccd2, { metalness: 0.6 }), true), -A.w / 2 + 3 + i * (A.w - 6) / 8, 4.6, A.d / 2 + 0.18));
