  const as = signMesh('AQUATIC CENTRE', 12, 1.4, { bg: '#1f8fd0' }); as.position.set(A.x, 7.7, A.z + A.d / 2 + 0.25); scene.add(as);
  flatShape(rectPts(A.x, A.z + A.d / 2 + 10, A.w, 18), plazaMat, 0.036);
