  for (const [px, pz] of [[-3.5, -2.5], [3.5, -2.5], [-3.5, 2.5], [3.5, 2.5]]) h.add(at(meshOf(new T.CylinderGeometry(0.12, 0.14, 3, 6), M(0x6b4a2a), true), px, 1.5, pz));
