    const fee = Math.min(money(), PRICES.repair);
    exitVehicle(true);
    if (fee > 0) spend(fee, 'Repair fee', 'lost');
    splash('IMEHARIBIKA!', `${VEH[v.kind].name} wrecked. Repair fee ${tsh(fee)}`, 'bad');
