const sparks = [];
let sparkMesh = null;
function buildSparkles() { sparkMesh = new T.InstancedMesh(new T.SphereGeometry(0.06, 6, 4), new T.MeshBasicMaterial({ color: 0xffe28a }), 200); sparkMesh.count = 0; sparkMesh.frustumCulled = false; scene.add(sparkMesh); }
