  POLICE.held = d < 4.5 && ps < 3.5 ? POLICE.held + dt : Math.max(0, POLICE.held - dt);
  if (POLICE.held > 1.3) { endChase(true); return; }
  POLICE.lost = d > 150 ? POLICE.lost + dt : Math.max(0, POLICE.lost - dt * 0.5);
