  WEB.uid = u ? u.id : null; WEB.token = (s && s.access_token) || ''; WEB.email = (u && u.email) || ''; WEB.anon = !u || !!u.is_anonymous; WEB.admin = false;
  if (u && !WEB.anon) { try { const r = await WEB.sb.rpc('is_admin'); WEB.admin = !!r.data; } catch (e) {} }
