  const drawMock = (id) => { scr.innerHTML = ''; try { if (id) renderBrand(scr, id, () => drawMock(null)); else renderPhoneHome(scr, (sid) => drawMock(sid)); } catch (e) { console.error(e); } };
  drawMock(null);
