  const dm = /^(?:Digit|Numpad)(\d)$/.exec(e.code || ''), n = dm ? +dm[1] : parseInt(k, 10); if (n >= 1 && n <= 8) { const b = $('#hpActs').children[n - 1]; if (b && !b.disabled) b.click(); return true; }
