  for (const th2 of thieves) { if (th2.state !== 'flee' && th2.state !== 'rush') continue; let [x, y] = toR(th2.x, th2.z); if (!inside(x, y, 10)) [x, y] = clampE(x, y, 12); c.beginPath(); c.arc(x, y, 8 + Math.sin(t * 10) * 2, 0, TAU); c.fillStyle = '#ff4a3a'; c.fill(); }
