const VOICE = { cur: null };
function voiceSrc(id) { const L = LINES[id]; return `voices/${LANG === 'sw' ? 'sw' : 'en'}/${id}${L && L.who === 'me' ? (state.look && state.look.f ? '_f' : '_m') : ''}.mp3`; }
