    r.addEventListener('input', () => { SETTINGS[key] = parseFloat(r.value) || SETTINGS[key]; save(store, String(SETTINGS[key])); document.querySelectorAll(`[data-range="${name}"]`).forEach(o => { if (o !== r) o.value = SETTINGS[key]; }); if (after) after(); });
