// called once the website backend is known (multiplayer start): names come alive only on afconcity.com
function menuOnline() { if (!nickOnline()) return; nickLoadMine(); onWebAuth((ev) => { if (ev === 'SIGNED_IN') nickLoadMine(); }); }
